local ActivityDirectDrawMgr = Class("ActivityDirectDrawMgr", Singleton)

---初始化数据Component
function ActivityDirectDrawMgr:__init()
    self.config = {
        currencyCount = {}
    }
    self.config.currencyCount[1] = 1
    self.config.currencyCount[2] = 10


    ---@type ActivityDirectDrawComponent
    self._directDrawComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityDirectDrawComponent)
end

---释放数据Component
function ActivityDirectDrawMgr:__delete()
end

--region public
function ActivityDirectDrawMgr:FreeProductBuyReq(activityUuid, productId, cb)
    local requestData = {
        activityUuid = activityUuid,
        productId = productId
    }
    GameUtils.Request(Interfaces.orientationCallFreeBuy, requestData, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        local rewards = checkTable(jsonData.rewards)
        if #rewards > 0 then
            GoodsUtils.DrawRewards(rewards)
            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
        end
        if cb then
            cb()
        end
    end)
end

function ActivityDirectDrawMgr:ShoppingMallReq(activityUuid)
    local requestData = { activityUuid = activityUuid }
    GameUtils.Request(Interfaces.OrientationCallMall, requestData, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        self._directDrawComponent:FillDirectDrawMallProductList(jsonData.orientationCallProductInfo)
        Events.Broadcast(Constants.EventNames.ActivityDirectDrawShoppingMallDataReq)
    end)
end

function ActivityDirectDrawMgr:StartDrawReq(activityUuid, callType, cb)
    local requestData = {
        activityUuid = activityUuid,
        callType = checkString(callType)
    }
    GameUtils.Request(Interfaces.OrientationCall, requestData, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = checkTable(response.data)
        local specialEffects = checkTable(jsonData.rewardsSpecialEffects)
        for i, reward in ipairs(jsonData.rewards) do
            reward.specialEffect = specialEffects[i]
        end
        if cb then
            cb(jsonData)
        end
    end)
end

function ActivityDirectDrawMgr:ActivityHomeReq(activityUuId)
    GameUtils.Request(Interfaces.OrientationCallHome, { activityUuid = activityUuId }, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        self._directDrawComponent:FillDirectDrawHomeDojo(jsonData)

        Events.Broadcast(Constants.EventNames.ActivityDirectDrawRefreshData)
    end)
end

function ActivityDirectDrawMgr:UpdateHomeDojo(activityUuid)
    GameUtils.Request(Interfaces.OrientationCallHome, {activityUuid=activityUuid}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        self._directDrawComponent:UpdateDirectDrawHomeDojo(jsonData)
        Events.Broadcast(Constants.EventNames.ActivityDirectDrawRefreshData)
    end)
end

