function ActivityDirectDrawMgr:ExchangeActivityCurrency(drawType, cb)
    --- 需要支付的活动货币数量
    local needCount = 1
    if drawType == 2 then
        needCount = 10
    end
    local activityDojo = self._directDrawComponent:GetActivityDojo()
    --- 你拥有的活动货币的数量
    local haveCount = GoodsUtils.GetThingNo(activityDojo.currency.id)
    --- 需要交换的活动货币的数量
    local exchangeCount = needCount - haveCount
    if exchangeCount <= 0 then
        --GameUtils.Toast(localize("活动货币充足无需兑换"))
        return
    end

    local homeDojo = self._directDrawComponent:GetDirectDrawHomeDojo()
    local exchangeInfo = homeDojo.exchange[checkString(activityDojo.currency.id)]
    local exchangeRate = checkNumber(exchangeInfo.consumeNum) / checkNumber(exchangeInfo.getNum)

    --- 需要支付的猫眼石数量
    local needPay = checkInt(math.floor(exchangeCount * exchangeRate))

    --- 你拥有的猫眼石数量
    local youHave = GoodsUtils.GetThingNo(exchangeInfo.consumeId)

    if youHave >= needPay then
        --- 猫眼石充足，是否用猫眼石交换活动货币，并开始抽卡？
        UIModule.OpenDialog({
            id = Constants.UITypeIds.GachaponConfirm,
            parameters = {
                type = GachaponConstants.ConfirmType.IconToIcon,
                poolType = GachaponConstants.PoolType.Regular,
                onConfirm = function()
                    if cb then
                        cb(exchangeInfo.consumeId, needPay)
                    end
                end,
                leftParam = {
                    goodsId = exchangeInfo.consumeId,
                    num = needPay
                },
                rightParam = {
                    goodsId = activityDojo.currency.id,
                    num = exchangeCount
                }
            }
        })
    else
        --- 猫眼石不足请前往兑换
        --GoodsUtils.ShowCommonLackMaterialDialog({{goodsId = exchangeInfo.consumeId, num = exchangeCount }})
        UIModule.OpenDialog({id = Constants.UITypeIds.UIActivityDirectDrawPurchaseDialog})
    end
end

---ChangeResearchCard 研究方向变更
---@param targetCardId number 变更的角色卡牌ID
function ActivityDirectDrawMgr:ChangeResearchCard(targetCardId, cb)
    local requestData = {
        activityUuid = self._directDrawComponent:GetActivityDojo().id,
        cardId = checkNumber(targetCardId)
    }
    GameUtils.Request(Interfaces.OrientationCallChoose, requestData, function(request, response)
        self._directDrawComponent:SetPlayerSelectCardId(targetCardId)
        if cb then
            cb()
        end
    end)
end
--endregion public

function ActivityDirectDrawMgr:IsFirstEnterActivity()
    local activityDojo = self._directDrawComponent:GetActivityDojo()

    if isNull(activityDojo) then
        return false
    end

    local key = string.format("FirstAccessDirectDrawPage%s", checkString(activityDojo.activityContentId))

    local firstStr = CfUtils.GetLocalData(key, "true")
    return firstStr == "true"
end

function ActivityDirectDrawMgr:PlayVideo()
    local activityDojo = self._directDrawComponent:GetActivityDojo()
    local planVo = ActivityDirectDrawMgr:LoadPlanVoById(activityDojo.activityContentId)
    if isNull(activityDojo) or isNull(planVo) then
        return
    end

    local key = string.format("FirstAccessDirectDrawPage%s", checkString(activityDojo.activityContentId))
    CfUtils.WriteLocalData(key, "false")

    UIModule.OpenDialog(UIArgs(Constants.UITypeIds.MoviePreviewDialog, {
        moviePath = planVo.video,   -- "Movie/op_oversea.usm",
        width = 1920, height = 1080,
    }))
end

return ActivityDirectDrawMgr